const styles = StyleSheet.create({
  card: { margin: 16, padding: 16, borderRadius: 12, backgroundColor: '#f0f9ff' },
  title: { fontSize: 20, fontWeight: '600', marginBottom: 8 },
  body: { fontSize: 16 },
  note: { fontSize: 14, marginTop: 12, color: '#475569' },
});

